// Generated by the `env-gallery` plugin (scripts/vite-gallery.ts) from the files in public/gallery.
declare module 'virtual:gallery' {
  export type GalleryItem = {
    id: string
    type: 'image' | 'video'
    /** Viewer source: 2000px WebP for photos, the original file for videos. */
    src: string
    /** 900px WebP for the grid (photos only). */
    thumb: string | null
    width: number | null
    height: number | null
    title: string | null
    caption: string | null
    album: string | null
    /** Local date ("2026-10-09") or date-time ("2026-10-09T13:19") from the file name. */
    taken: string | null
    modified: number
  }
  export const gallery: GalleryItem[]
}
